cssCode:
.cyber-loader {
  width: 80px;
  height: 80px;
  border: 5px solid transparent;
  border-top: 5px solid #00ffcc;
  border-right: 5px solid #00ffcc;
  border-radius: 50%;
  animation: spinCyber 1s linear infinite;
  position: relative;
}
.cyber-loader::before {
  content: '';
  position: absolute;
  top: 10px; left: 10px; right: 10px; bottom: 10px;
  border: 5px solid transparent;
  border-bottom: 5px solid #ff00ff;
  border-left: 5px solid #ff00ff;
  border-radius: 50%;
  animation: spinCyberReverse 2s linear infinite;
}
@keyframes spinCyber { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
@keyframes spinCyberReverse { 0% { transform: rotate(360deg); } 100% { transform: rotate(0deg); } }

